    if(!id){const reuse=String(data.get('reuseId')||'');const histories=new Map(Object.values(state.rosters).flat().filter(m=>m.name===name&&m.department===dep).map(m=>[m.id,m]));if(reuse==='new')memberId=E.uid();else if(reuse){const chosen=Object.values(state.rosters).flat().find(m=>m.id===reuse);if(!chosen||chosen.name!==name||chosen.department!==dep)throw Error('复用身份的姓名和部门必须一致');memberId=reuse;}else if(histories.size===1)memberId=[...histories.keys()][0];else if(histories.size>1)throw Error('存在多个同名历史身份，请选择复用身份');else memberId=E.uid();if(roster().some(m=>m.id===memberId))throw Error('此成员已在本期名单中；如为同名的另一人，请选择“明确建立新身份”');}
