  function editableWechatPreview(w,c){const members=new Map();w.participants.forEach((p,index)=>{if(!members.has(p.memberId))members.set(p.memberId,{...p,parts:[]});members.get(p.memberId).parts.push({p,index});});const lines=new Map(c.lines.map(l=>[l.memberId,l])),rows=[...members.values()];previewPersonPage=Math.max(1,Math.min(previewPersonPage,Math.ceil(rows.length/10)||1));const selected=rows.filter(p=>previewSelected.has(p.memberId)).length;const active=table(['<input type="checkbox" data-preview-all '+(rows.length&&selected===rows.length?'checked':'')+' aria-label="选择预览全部人员">','姓名','分工','基础工资（元）','奖励（元）','合计（元）','计算依据','移除'],rows.map(p=>{const l=lines.get(p.memberId);return ['<input type="checkbox" data-preview-selected="'+esc(p.memberId)+'" '+(previewSelected.has(p.memberId)?'checked':'')+' aria-label="选择预览人员'+esc(p.name)+'">',esc(p.name),'<div class="preview-role-controls">'+p.parts.map(({p,index})=>roleControl(w,p.role,'data-part="'+index+'" data-key="role"',p.name)).join('')+'</div>',E.money(l?.baseCents||0),E.money(l?.bonusCents||0),E.money(l?.totalCents||0),'<div class="wrap-text">'+esc(l?.basis||'请确认分工及基础信息')+'</div>',button('移除','moveToReview',p.memberId,'danger')];}),'editable-preview-table');const review=w.reviewParticipants||[];reviewPersonPage=Math.max(1,Math.min(reviewPersonPage,Math.ceil(review.length/10)||1));const count=review.filter(p=>reviewSelected.has(p.id)).length;return '<div class="fee-preview"><div class="preview-section-head"><h3>预览</h3><div class="action-cluster"><span>已选 '+selected+' 人</span>'+button('全部选择','selectPreview')+button('取消选择','clearPreview')+button('批量移除','moveSelectedToReview','','danger')+'</div></div>'+(c.errors.length?(w.type==='视频'?'':'<div class="validation-errors">'+c.errors.map(esc).join('\n')+'</div>'):'<p><span class="status-good">可保存稿费</span></p>')+active+'<p class="subtle">共 '+rows.length+' 人，最多展示5条，可滚动查看。</p>'+previewTotals(c)+'<div class="preview-section-head review-section-head"><h3>复核</h3><div class="action-cluster"><span>已选 '+count+' 人</span>'+button('全部选择','selectReview')+button('取消选择','clearReview')+button('批量算入','includeSelectedReview','','primary')+'</div></div><p class="subtle">以下人员当前不计入稿费。选择分工后点击算入，可返回预览；名单外人员不会列入。</p>'+table(['<input type="checkbox" data-review-all '+(review.length&&count===review.length?'checked':'')+' aria-label="选择复核全部人员">','人名','分工','是否算入'],review.slice((reviewPersonPage-1)*10,reviewPersonPage*10).map(p=>['<input type="checkbox" data-review-selected="'+esc(p.id)+'" '+(reviewSelected.has(p.id)?'checked':'')+' aria-label="选择复核人员'+esc(p.name)+'">',(p.memberId?esc(p.name):memberField('',w.month,'data-review-row="'+esc(p.id)+'" data-review-key="memberId"',false,p.name))+'<div class="source-label">'+esc(p.reason||'请选择分工')+'</div>','<div class="preview-role-controls">'+p.assignments.map((part,j)=>roleControl(w,part.role,'data-review-row="'+esc(p.id)+'" data-review-assignment="'+j+'"',p.name)).join('')+'</div>',button('算入','includeReview',p.id,'primary')]),'review-people-table')+pageBar(review.length,reviewPersonPage,'reviewPersonPage')+button('添加复核人员','addReviewPerson')+'</div>';}
  function newWork(){wechatStep='credits';const video=page==='video',w={id:E.uid(),code:'W-'+Date.now().toString(36).toUpperCase(),month:state.month,title:'',platform:video?'视频号':'学校官微',type:video?'视频':'官微图文',channel:video?'video':'wechat',original:null,views:'',link:'',durationSeconds:'',videoRate:'',publishCount:'',rates:{},extraReward:'',extraRewardNote:'',participants:[],source:'表单录入',distinctFrom:[],createdAt:new Date().toISOString()};state.drafts.push(w);save();editDraft(w.id);}
