  function creditsPanel(w){const parsed=w.creditsText?FeeCredits.parse(w.creditsText,roster(w.month),w.original,E.workRules(w,state)):null,preview=parsed?FeeCredits.preview(parsed):null;return '<fieldset class="credits-panel"><legend>粘贴官微分工</legend><p class="subtle">文 → 文字'+E.effectiveRules(state.rules).fixed.文字+'元；图 → 图片'+E.effectiveRules(state.rules).fixed.图片+'元；统筹 → 策划'+E.effectiveRules(state.rules).fixed.策划+'元（最多3人）；微信编辑 → 原创'+E.effectiveRules(state.rules).fixed.原创编辑+'元 / 非原创'+E.effectiveRules(state.rules).fixed.非原创编辑+'元。只让当前周期名单中的人员分配；初审、复审、终审不计稿费。</p><textarea name="creditsText" rows="8" placeholder="文：张三 李四\n图：王五\n赵六\n统筹：张三\n微信编辑：李四">'+esc(w.creditsText||'')+'</textarea><div class="toolbar">'+button('识别并填入分工','parseCredits','','primary')+'</div>'+(preview?table(['输入行 / 分工','岗位总额','计入人员','名单外（不计入）','每人稿费','说明'],preview.rows.map(r=>[esc(r.label),r.amount===null?'待确认 / 不计费':r.amount+'元','<div class="wrap-text">'+esc(r.eligible.join('、')||'无')+(r.ambiguous.length?'<br>同名待选择：'+esc(r.ambiguous.join('、')):'')+'</div>','<div class="wrap-text">'+esc(r.excluded.join('、')||'无')+'</div>',r.amount===null?'—':E.money(r.perPersonCents)+'元','<div class="wrap-text">'+esc(r.note)+'</div>']))+'<p class="subtle">以上为各行分工份额试算；各小项先均分并截断，再累加到个人基础费，最终个人金额以下方预览为准；阅读量奖励在下方计算。重复提及的同一岗位人员会去重，续行沿用上一行分工。'+esc(parsed.warnings.join('；'))+'</p>':'')+'</fieldset>';}
  function applyCredits(preserve=false){if(!editor.creditsText?.trim())throw Error('请先粘贴官微分工文本');const parsed=FeeCredits.parse(editor.creditsText,roster(editor.month),editor.original,E.workRules(editor,state));if(!parsed.participants.length&&!parsed.reviewCandidates.length)throw Error('没有识别到名单内人员，请检查姓名和本周期名单');if(preserve)R.syncOriginal(editor);else {R.reset(editor,parsed);previewSelected.clear();reviewSelected.clear();}editor.creditsApplied=true;editor.source='官微分工文本识别';editor.note=(editor.note||'').replace(/\n?【名单核对】[\s\S]*$/,'')+'\n【名单核对】'+parsed.groups.filter(g=>g.excluded.length).map(g=>g.label+'名单外不计入：'+g.excluded.join('、')).join('；');notice('已识别分工；未识别工作或未确认身份的人员列入复核，算入后才参与稿费分配。');}
  function duplicateHTML(w){const d=E.duplicates(state,candidate(w)),all=[...d.exact,...d.suspected];if(!all.length)return '';return '<fieldset><legend>重复作品核对</legend><p class="subtle">同编号或同链接不能再次计入。同名作品可确认是不同作品；重复视频请选择制作来源与计奖平台。</p>'+all.map(x=>'<p>'+esc(x.code+' / '+x.month+' / '+x.platform+' / '+x.title)+' '+button('查看原记录','peekWork',x.id)+'</p>'+(d.suspected.includes(x)?'<label class="inline-check"><input type="checkbox" data-distinct="'+esc(x.id)+'" '+((w.distinctFrom||[]).includes(x.id)?'checked':'')+'>确认与该记录是不同作品（仅标题相同）</label>':'')).join('')+(w.type==='视频'&&all.some(x=>x.type==='视频')?button('处理重复视频','resolveVideo'):'<p class="subtle">请编辑原记录，或移除不保留的记录后继续核对。</p>')+'</fieldset>';}
  function renderEditor(){if(E.channelFor(editor)==='wechat'){renderWechatEditor();return;}if(editor.videoPricing==='perSecond'){renderVideoEditor();return;}const w=editor,isVideo=w.type==='视频',ops=w.type==='账号运营';const participants=w.participants.map((p,i)=>[memberField(p.memberId,w.month,'data-part="'+i+'" data-key="memberId"',false,p.name),'<select data-part="'+i+'" data-key="role"><option value="">请选择分工</option>'+[...new Set([...E.roles(w.type,E.workRules(w,state)),...(p.role&&!E.roles(w.type,E.workRules(w,state)).includes(p.role)?[p.role]:[])])].map(r=>'<option '+(p.role===r?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select>',...(isVideo||ops?['<input type="number" min="0" max="100" step="0.0001" data-part="'+i+'" data-key="share" value="'+esc(p.share||'')+'" placeholder="留空均分">']:[]),button('移除','removePart',String(i))]);
    const body='<div class="work-form">'+(E.channelFor(w)==='wechat'?creditsPanel(w):'')+'<div class="form-grid">'+field('归属周期','month',w.month,'text',periodOptions(w.month))+field('发布日期（统计表使用）','publicationDate',w.publicationDate||'','date')+field('作品编号','code',w.code)+field('作品标题','title',w.title)+field('作品类型','type',w.type,'text',E.channelFor(w)==='video'?E.TYPES.filter(t=>['视频','账号运营'].includes(t)):E.TYPES.slice(0,2))+field('发布平台','platform',w.platform,'text',E.PLATFORMS)+field('作品链接（可选）','link',w.link)+(!ops?field('原创状态（需确认）','original',w.original===true?'true':w.original===false?'false':'','text',[{value:'',label:'待确认'},{value:'true',label:'原创'},{value:'false',label:'非原创'}])+field(isVideo?'播放量（计奖数据）':'阅读量','views',w.views,'number',null,'min="0" step="1"'):'')+(isVideo?field('时长（秒）','durationSeconds',w.durationSeconds,'number',null,'min="0"')+(w.videoPricing==='perSecond'?'':field('单价（30–60元/分钟）','videoRate',w.videoRate,'number',null,'min="30" max="60"'))+field('计奖平台','rewardPlatform',w.rewardPlatform||w.platform,'text',E.PLATFORMS)+field('额外奖励（超过200000播放量）','extraReward',w.extraReward,'number',null,'min="0"')+field('额外奖励确认依据','extraRewardNote',w.extraRewardNote):ops?field('实际发布次数','publishCount',w.publishCount,'number',null,'min="1" step="1"'):'')+'</div>'+'<div class="form-section">参与人与分工</div><p class="subtle">'+(isVideo||ops?'每个岗位内默认均分，自定义比例合计100%。':'官微所有小项一律均分，不可修改比例。')+'同一人兼任不同岗位可新增多行。老师不得计入。</p>'+table(['参与人','岗位',...(isVideo||ops?['岗位内比例（%）']:[]),'操作'],participants)+button('添加参与分工','addPart')+(!roster(w.month).length?'<p class="error">该双月周期暂无成员名单，请先关闭表单并准备名单；未保存的表单不会入账。</p>':'')+'<label>备注<textarea name="note">'+esc(w.note||'')+'</textarea></label><div class="source-label">来源：'+esc(w.source)+' '+(w.replacesId?'；编辑确认前，原作品继续计入稿费。':'')+'</div>'+duplicateHTML(w)+(w.duplicateNote?'<p class="draft-note">重复核对：'+esc(w.duplicateNote)+'</p>':'')+'<div id="feePreview">'+previewHTML(w)+'</div><div class="dialog-foot fee-form-actions">'+button('刷新试算','refreshPreview')+button('保存稿费','confirmEditor','','primary')+'</div></div>';
    openDialog(E.channelFor(w)==='wechat'?'官微稿费 · 录入':'视频组稿费 · 录入',body,'work',true);}
  function renderWechatEditor(){const w=editor;if(wechatStep==='credits'){openDialog(w.replacesId?'编辑官微项目 · 分工':'新建项目 · 输入分工','<div class="work-form"><p class="subtle">直接粘贴公众号末尾的分工名单，每项不同的分工都要换行。</p><label>参与人员<textarea name="creditsText" rows="10" placeholder="文：张三 李四&#10;图：王五&#10;统筹：张三&#10;微信编辑：李四">'+esc(w.creditsText||'')+'</textarea></label><div class="dialog-foot">'+button('下一步：基础信息','wechatNext','','primary')+'</div></div>','work',true);return;}const parsed=FeeCredits.parse(w.creditsText||'',roster(w.month),w.original,E.workRules(w,state)),pre=FeeCredits.preview(parsed),calc=E.calculate(w,state);const stats=wechatStatsPreview(w);const participants=w.participants.map((p,i)=>[memberField(p.memberId,w.month,'data-part="'+i+'" data-key="memberId"',false,p.name),'<select data-part="'+i+'" data-key="role">'+[...new Set([...E.roles(w.type,E.workRules(w,state)),p.role])].filter(Boolean).map(r=>'<option '+(r===p.role?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select>',button('移除','removePart',String(i))]);openDialog(w.replacesId?'编辑官微项目 · 基础信息':'新建项目 · 基础信息','<div class="work-form"><p class="subtle">归属周期：'+esc(E.periodLabel(w.month))+'；稿费按本周期名单与当前规则计算。</p><div class="form-grid">'+field('日期','publicationDate',w.publicationDate||'','date')+field('官微标题','title',w.title)+field('阅读量','views',w.views,'number',null,'min="0" step="1" placeholder="只能填写数字，1.2w需填成12000"')+field('原创状态（决定编辑金额与阅读量奖励）','original',w.original===true?'true':w.original===false?'false':'','text',[{value:'',label:'请选择原创或非原创'},{value:'true',label:'原创'},{value:'false',label:'非原创'}])+'</div><details><summary>参与人员原文与匹配结果</summary><pre class="statistics-text">'+esc(w.creditsText||'')+'</pre>'+table(['输入分工','计入人员','名单外（不计入）'],pre.rows.map(r=>[esc(r.label),esc(r.eligible.join(' ')),esc(r.excluded.join(' '))]))+'</details>'+duplicateHTML(w)+'<div id="feePreview">'+previewHTML(w)+stats+'</div><div class="dialog-foot fee-form-actions">'+button('上一步：分工原文','wechatBack')+button('刷新试算','refreshPreview')+button('保存稿费','confirmEditor','','primary')+'</div></div>','work',true);}
  function wechatStatsPreview(w){const calc=E.calculate(w,state);let stats='';if(calc.valid){const row=I.wechatRows({...state,works:[candidate(w)]},w.month)[0];stats=table(['日期','官微标题','参与人员','阅读量','稿费','总稿费'],[[esc(row.dateDisplay),esc(row.title),'<div class="statistics-text">'+esc(row.credits)+'</div>',esc(row.views),'<div class="statistics-text">'+esc(row.calculation)+'</div>',E.money(row.totalCents)]],'wechat-statistics');}return stats;}
  function captureEditor(){if(!editor||dialogKind!=='work')return;const root=$('dialogContent');for(const node of root.querySelectorAll('[name]')){if(node.name.startsWith('rate-')){editor.rates??={};editor.rates[node.name.slice(5)]=node.value;}else if(node.name==='original')editor.original=node.value===''?null:node.value==='true';else editor[node.name]=node.value;}
    for(const node of root.querySelectorAll('[data-part]')){const p=editor.participants[Number(node.dataset.part)];if(p){if(node.dataset.key==='role'&&p.role!==node.value)p.manualRole=true;p[node.dataset.key]=node.value;if(node.dataset.key==='memberId'){const m=roster(editor.month).find(m=>m.id===node.value);if(m){p.name=m.name;p.department=m.department;}}}}
    for(const node of root.querySelectorAll('[data-review-row]')){const row=(editor.reviewParticipants||[]).find(p=>p.id===node.dataset.reviewRow);if(!row)continue;if(node.dataset.reviewKey==='memberId'){row.memberId=node.value;const m=roster(editor.month).find(m=>m.id===node.value);if(m){row.name=m.name;row.department=m.department;}}else if(node.dataset.reviewAssignment!==undefined){const part=row.assignments[Number(node.dataset.reviewAssignment)];if(part&&part.role!==node.value){part.role=node.value;part.manualRole=true;}}}const unique=new Set();editor.participants=editor.participants.filter(p=>{const key=p.memberId+'|'+p.role;if(unique.has(key))return false;unique.add(key);return true;});
    editor.distinctFrom=[...root.querySelectorAll('[data-distinct]:checked')].map(n=>n.dataset.distinct);}
  function stashEditor(){if(!editor)return;const i=state.drafts.findIndex(w=>w.id===editor.id);if(i>=0)state.drafts[i]=E.clone(editor);}
  function editorInput(e){if(dialogKind!=='work'||!editor)return;if(e.target.matches('[data-preview-selected],[data-preview-all],[data-review-selected],[data-review-all]')){if(e.target.hasAttribute('data-preview-all')){previewSelected.clear();if(e.target.checked)editor.participants.forEach(p=>previewSelected.add(p.memberId));}else if(e.target.hasAttribute('data-review-all')){reviewSelected.clear();if(e.target.checked)(editor.reviewParticipants||[]).forEach(p=>reviewSelected.add(p.id));}else {const isPreview=e.target.hasAttribute('data-preview-selected'),set=isPreview?previewSelected:reviewSelected,id=isPreview?e.target.dataset.previewSelected:e.target.dataset.reviewSelected;if(e.target.checked)set.add(id);else set.delete(id);}refreshFeePreview();return;}captureEditor();if(e.type==='input'&&e.target.name==='creditsText')editor.creditsApplied=false;if(e.type==='change'&&editor.creditsApplied&&['original','month'].includes(e.target.name))applyCredits(e.target.name==='original');stashEditor();if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=null;save();},200);if(e.type==='change'&&['type','month','original'].includes(e.target.name)){renderEditor();return;}if(e.type==='change'){refreshFeePreview();}}
  function applyDraft(id){const draft=state.drafts.find(w=>w.id===id);if(!draft)throw Error('草稿已不存在');if(draft.creditsText&&!draft.creditsApplied)throw Error('分工文本有变动，请重新点击“识别并填入分工”再确认');const w=candidate(draft),c=E.canConfirm(state,w);if(!c.valid)throw Error(c.errors.join('\n'));const removeIds=new Set([...(w.supersedesIds||[]),...(draft.replacesId?[draft.replacesId]:[])]);state.works=state.works.filter(x=>!removeIds.has(x.id));w.confirmedAt=new Date().toISOString();w.updatedAt=w.confirmedAt;state.works.push(w);state.drafts=state.drafts.filter(x=>x.id!==id);audit('确认作品',w.code+' / '+w.title+'；'+E.money(c.actualCents)+'元');return c;}
  function confirmEditor(){captureEditor();if(E.channelFor(editor)==='wechat'){if(!/^\d{4}-\d{2}-\d{2}$/.test(editor.publicationDate||''))throw Error('请填写日期');}stashEditor();const c=applyDraft(editor.id);editor=null;$('dialog').close();dialogKind='';commit('保存作品稿费');notice('作品已保存，实发 '+E.money(c.actualCents)+' 元。');if(sessionWorks.length){const next=sessionWorks.shift();state.drafts=[next];editDraft(next.id);}}
  function confirmAll(){let count=0;for(const w of [...channelDrafts()]){if(E.canConfirm(state,candidate(w)).valid){applyDraft(w.id);count++;}}commit('批量确认作品',count+'件');notice('已确认 '+count+' 件作品；其余仍保留在待核对列表。');}
  let detailContext=null;
