  async function exportBackup(local=true){const zip=new JSZip();zip.file('稿费备份.json',JSON.stringify(I.backup(state),null,2));await exportBlob(await zip.generateAsync({type:'blob'}),'记者团稿费备份_'+new Date().toISOString().replace(/[:.]/g,'-')+'.zip',local);}
  async function restoreFile(file){if(file.size>100*1024*1024)throw Error('备份文件过大');let data;if(file.name.toLowerCase().endsWith('.zip')){const zip=await JSZip.loadAsync(await file.arrayBuffer()),entry=zip.file('稿费备份.json');if(!entry)throw Error('不是稿费备份包，请勿导入绩效包');data=JSON.parse(await entry.async('string'));}else data=JSON.parse(await file.text());const restored=I.restore(data);if(!confirm('将用备份替换所有周期稿费数据。系统会先下载当前备份。继续？'))return;await exportBackup(false);state=restored;viewMonth=state.month;readFailed=false;loading=false;editor=null;page='personal';department='';search='';rosterPage=1;await save();render();notice('稿费备份已恢复。API Key不在备份中。');}
